param([Parameter(Mandatory=$true)][string]$RunDirectory,[switch]$Flagged,[switch]$MatchingResult,[switch]$Plan,[switch]$FallbackResult)
$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;$target=Join-Path $root 'evidence/mpu4/skill-cash';$stem=if($FallbackResult){'fallback-result-matrix'}elseif($Plan){'nudge-plan-matrix'}elseif($MatchingResult){'matching-result-matrix'}elseif($Flagged){'flagged-availability-matrix'}else{'availability-matrix'}
if($FallbackResult -and ((Get-Content (Join-Path $RunDirectory 'exit-code.txt') -Raw).Trim() -ne '0')){throw 'Incomplete fallback capture'}
$log=[IO.File]::ReadAllText((Join-Path $RunDirectory 'debug.log'));if($FallbackResult -and $log -match '(?m)^Error in expression:'){throw 'Debugger expression errors invalidate fallback matrix'};$cases=Get-Content (Join-Path $RunDirectory 'cases.json') -Raw|ConvertFrom-Json;$rows=[Collections.Generic.List[object]]::new()
foreach($case in $cases){
 $before=[IO.File]::ReadAllBytes((Join-Path $RunDirectory ($case.id+'-before.bin')));$after=[IO.File]::ReadAllBytes((Join-Path $RunDirectory ($case.id+'-after.bin')))
 if($before.Length -ne 2048 -or $after.Length -ne 2048){throw 'Incomplete matrix RAM'}
 $match=[regex]::Match($log,('(?m)^MATRIX '+[regex]::Escape($case.id)+' (.*)$'));if(!$match.Success){throw 'Missing matrix exit'}
 $values=[ordered]@{};foreach($f in [regex]::Matches($match.Groups[1].Value,'(\w+)=([0-9A-F]+)')){$values[$f.Groups[1].Value]=[Convert]::ToUInt16($f.Groups[2].Value,16)}
 $rows.Add([ordered]@{id=$case.id;kind=$case.kind;before_hex=[Convert]::ToHexString($before);expected_low_ram_sha256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([byte[]]$after[0..0x6FF]));exit=$values;before_sha256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($before));after_sha256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($after))})
}
[ordered]@{classification=$(if($FallbackResult){'Synthetic isolated native1AF1 full pair award or exactly-two-flag0 fallback; IRQ masked, explicit setup, not a natural game path'}elseif($Plan){'Synthetic isolated native2A2F movement-plan and1AC3 lookup matrix; IRQ masked; explicit setup, not a natural game path'}else{'Synthetic isolated native search/lookup matrix; IRQ masked; explicit setup, not a natural game path'});compared_ram_end_exclusive=0x700;excluded='Native CPU S-stack save/return residue at 0700..07FF is not translated';cases=@($rows.ToArray());capture=(Get-Content (Join-Path $RunDirectory 'provenance.json') -Raw|ConvertFrom-Json);raw_sha256=(Get-FileHash (Join-Path $RunDirectory 'debug.log')).Hash}|ConvertTo-Json -Depth 7|Set-Content (Join-Path $target ($stem+'.json'))
Copy-Item (Join-Path $RunDirectory 'debugger.cmd') (Join-Path $target ($stem+'-debugger.cmd'))
